insert into grammar_topics (unit, section, title, summary) values
  (1, 'Present', 'am/is/are', 'Глагол to be в настоящем времени: I am; he/she/it is; we/you/they are. Краткие формы: I''m, he''s, it''s, we''re, they''re. Отрицание — добавляем not: I''m not, he isn''t, they aren''t.'),
  (2, 'Present', 'am/is/are (questions)', 'В вопросе am/is/are встаёт перед подлежащим: Am I…? Is it…? Are you…? Вопросительное слово — в самом начале: Where is…? Короткие ответы: Yes, I am. / No, it isn''t. В утвердительном коротком ответе сокращать нельзя: Yes, I am (не Yes, I''m).'),
  (3, 'Present', 'I am doing (present continuous)', 'Present continuous = am/is/are + глагол с -ing. Так говорят о том, что происходит сейчас, в момент речи: I''m working. She isn''t listening. Орфография: write → writing (немая e выпадает), run → running (согласная удваивается), lie → lying.'),
  (4, 'Present', 'are you doing? (present continuous questions)', 'Вопрос в present continuous: am/is/are ставим перед подлежащим, затем глагол с -ing: Are you working? What is she doing? Where are they going? Короткие ответы: Yes, I am. / No, he isn''t.'),
  (5, 'Present', 'I do/work/like etc. (present simple)', 'Present simple: I/you/we/they work, но he/she/it works — в 3-м лице единственного числа добавляем -s. Время для того, что бывает регулярно, всегда или вообще верно: I work in IT. The office opens at nine. Орфография: после s, sh, ch, x, o пишем -es (watches, goes, does); согласная + y → -ies (study → studies); have → has.'),
  (6, 'Present', 'I don''t … (present simple negative)', 'Отрицание в present simple: I/you/we/they don''t + глагол; he/she/it doesn''t + глагол. После doesn''t глагол без -s: She doesn''t work (не doesn''t works). don''t = do not, doesn''t = does not.'),
  (7, 'Present', 'Do you …? (present simple questions)', 'Вопрос в present simple: Do + I/you/we/they + глагол? Does + he/she/it + глагол? После does глагол без -s: Does she work…? Вопросительное слово — в начале: Where do you live? What does it mean? Короткие ответы: Yes, I do. / No, she doesn''t.'),
  (8, 'Present', 'I am doing (present continuous) and I do (present simple)', 'Present continuous (am/is/are + -ing) — то, что происходит сейчас или в эти дни: I''m fixing a bug right now. Present simple — привычки, регулярные действия, факты: I fix bugs every day. Глаголы know, like, want, need, understand, mean, prefer, believe, remember обычно не ставят в continuous: I know (не I''m knowing).'),
  (9, 'Present', 'I have … and I''ve got …', 'Have и have got значат одно и то же — «иметь»: I have a laptop = I''ve got a laptop; he/she/it has = has got. Отрицание: I don''t have = I haven''t got. Вопрос: Do you have…? = Have you got…? Не смешивай формы: Do you have… (не Have you have…). В прошедшем времени только had: I had a cold last week.'),
  (10, 'Past', 'was/were', 'Прошедшее время глагола to be: I/he/she/it was; we/you/they were. Отрицание: wasn''t, weren''t. Вопрос: Was she…? Were you…? Короткие ответы: Yes, I was. / No, they weren''t.'),
  (11, 'Past', 'worked/got/went etc. (past simple)', 'Past simple — законченное действие в прошлом: I worked yesterday. Правильные глаголы получают -ed: work → worked, live → lived, stop → stopped, study → studied. Неправильные надо запомнить: go → went, get → got, have → had, see → saw, make → made, find → found, send → sent, write → wrote. Форма одна для всех лиц: I/he/they worked.'),
  (12, 'Past', 'I didn''t … Did you …? (past simple negative and questions)', 'Отрицание в past simple: didn''t + глагол в начальной форме, для всех лиц: I didn''t go (не didn''t went). Вопрос: Did + подлежащее + глагол: Did you see it? What did she say? Короткие ответы: Yes, I did. / No, they didn''t.'),
  (13, 'Past', 'I was doing (past continuous)', null),
  (14, 'Past', 'I was doing (past continuous) and I did (past simple)', null),
  (15, 'Present perfect', 'I have done (present perfect 1)', null),
