insert into grammar_exercises (topic_id, position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
select t.id, v.position, v.exercise_type::exercise_type, v.prompt, v.options, v.correct_answer, v.accepted_answers, v.explanation
from (values
  (1, 'multiple_choice', 'My name ___ Alex.', array['am', 'is', 'are']::text[], 'is', array[]::text[], 'My name = it → is.'),
  (2, 'multiple_choice', 'I ___ a backend developer.', array['am', 'is', 'are']::text[], 'am', array[]::text[], 'С I всегда am.'),
  (3, 'multiple_choice', 'The servers ___ in Frankfurt.', array['am', 'is', 'are']::text[], 'are', array[]::text[], 'The servers — множественное число → are.'),
  (4, 'fill_blank', 'We ___ in the same team. (be)', null::text[], 'are', array['''re']::text[], 'We → are.'),
  (5, 'fill_blank', 'The build ___ ready yet. (be, отрицание)', null::text[], 'isn''t', array['is not']::text[], 'The build = it → is not / isn''t.'),
  (6, 'multiple_choice', 'You ___ late. The meeting starts at ten.', array['am not', 'isn''t', 'aren''t']::text[], 'aren''t', array[]::text[], 'You → are not / aren''t.'),
  (7, 'multiple_choice', 'It ___ cold in the office today.', array['am', 'is', 'are']::text[], 'is', array[]::text[], 'It → is.'),
